def chain_of_few(uql, lul):
    tokens = []
    current = uql
    while True:
        tokens.append(current)
        next_token = None
        for token in lul:
            if token == current:
                next_token = token
                break
        if next_token is None:
            break
        current = next_token
    return tokens
